<div class="page-header"><div><h1 class="h3">Reports</h1><p class="text-muted mb-0">Server-generated reports from actual expense data.</p></div><a class="btn btn-outline-primary" href="<?=url('reports/csv?'.http_build_query($f))?>">Export CSV</a></div><div class="card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-3"><select class="form-select" name="category_id"><option value="">All Categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=selected($f['category_id']??'',$c['id'])?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="account_id"><option value="">All Accounts</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=selected($f['account_id']??'',$a['id'])?>><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="date" name="from" value="<?=e($f['from']??'')?>"></div><div class="col-md-2"><input class="form-control" type="date" name="to" value="<?=e($f['to']??'')?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Apply</button></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Amount</th><th>Category</th><th>Account</th><th>Description</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['category'])?></td><td><?=e($r['account'])?></td><td><?=e($r['description'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>